#!/usr/bin/env node
/**
 * ⚠️ NOTICE TO AI AGENTS / AUTOMATION ⚠️
 * DO NOT EDIT THIS FILE OR ANY OTHER FILES IN scripts/!
 * 
 * Modifying governance scripts will cause GitHub Actions CI to fail.
 * All checks are immutably verified on GitHub. 
 * To resolve validation errors, refactor or fix files under src/ instead.
 * 
 * scripts/verify-architecture.js
 * 
 * FSD ARKITEKTURVERIFIERING FÖR OUTREACH COORDINATION ENGINE (v10.4)
 * 
 * Mekanisk kontroll av lagerisolering och Feature-Sliced Design:
 * 1. Spärrar korsvisa beroenden mellan features (src/features/A -> src/features/B).
 * 2. Säkerställer de 4 tillåtna FSD-samverkansvägarna (EventBus, Shared, Widgets/Pages, Ticketklyvning).
 * 3. Förhindrar lagerinversion (src/shared/ får aldrig importera från överliggande lager).
 */

import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);

const fs = require('fs');
const path = require('path');
const ts = require('typescript');

const ROOT_DIR = process.cwd();
const SRC_DIR = path.join(ROOT_DIR, 'src');

if (!fs.existsSync(SRC_DIR)) {
  console.log('ℹ️ src/ katalogen finns inte ännu – hoppar över arkitekturkontroll.');
  process.exit(0);
}

// ============================================================================
// FILSKANNING & AST-PARSNING
// ============================================================================

function getAllSourceFiles(dir) {
  let results = [];
  const list = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of list) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (entry.name === 'node_modules' || entry.name === 'dist' || entry.name === '.git') {
        continue;
      }
      results = results.concat(getAllSourceFiles(fullPath));
    } else if (
      (entry.name.endsWith('.ts') || entry.name.endsWith('.tsx')) &&
      !entry.name.endsWith('.d.ts')
    ) {
      results.push(fullPath);
    }
  }

  return results;
}

function parseImports(filePath) {
  const fileContent = fs.readFileSync(filePath, 'utf-8');
  const sourceFile = ts.createSourceFile(
    filePath,
    fileContent,
    ts.ScriptTarget.Latest,
    true,
    filePath.endsWith('.tsx') ? ts.ScriptKind.TSX : ts.ScriptKind.TS
  );

  const imports = [];

  function visit(node) {
    // Statiska importer: import ... from '...'
    // Re-exporter: export ... from '...'
    if ((ts.isImportDeclaration(node) || ts.isExportDeclaration(node)) && node.moduleSpecifier) {
      if (ts.isStringLiteral(node.moduleSpecifier)) {
        const { line } = sourceFile.getLineAndCharacterOfPosition(node.getStart());
        imports.push({
          specifier: node.moduleSpecifier.text,
          line: line + 1,
        });
      }
    }
    // Dynamiska importer: import('...')
    if (ts.isCallExpression(node) && node.expression.kind === ts.SyntaxKind.ImportKeyword) {
      const arg = node.arguments[0];
      if (arg && ts.isStringLiteral(arg)) {
        const { line } = sourceFile.getLineAndCharacterOfPosition(node.getStart());
        imports.push({
          specifier: arg.text,
          line: line + 1,
        });
      }
    }
    ts.forEachChild(node, visit);
  }

  visit(sourceFile);
  return imports;
}

// ============================================================================
// PATH RESOLUTION & NORMALISERING
// ============================================================================

function resolveModulePath(callingFile, specifier) {
  // Ignorera externa bibliotek från node_modules
  if (!specifier.startsWith('.') && !specifier.startsWith('@/') && !specifier.startsWith('src/')) {
    return null;
  }

  let resolvedTarget = '';

  if (specifier.startsWith('@/')) {
    resolvedTarget = path.join(SRC_DIR, specifier.slice(2));
  } else if (specifier.startsWith('src/')) {
    resolvedTarget = path.join(ROOT_DIR, specifier);
  } else {
    resolvedTarget = path.resolve(path.dirname(callingFile), specifier);
  }

  return path.relative(ROOT_DIR, resolvedTarget).replace(/\\/g, '/');
}

function getFsdLayer(relPath) {
  const parts = relPath.split('/');
  if (parts[0] !== 'src' || parts.length < 2) return null;

  const layer = parts[1]; // features, shared, widgets, pages, app
  const slice = parts[2] || null; // ex. domännamnet under features/

  return { layer, slice };
}

// ============================================================================
// ARKITEKTURREGLER
// ============================================================================

function getModifiedFiles() {
  try {
    const { execSync } = require('child_process');
    const status = execSync('git status --porcelain', { encoding: 'utf-8', cwd: ROOT_DIR });
    return status
      .split('\n')
      .map((line) => line.trim())
      .filter((line) => line.length > 0)
      .map((line) => line.split(/\s+/).pop())
      .filter((file) => file && (file.endsWith('.ts') || file.endsWith('.tsx')))
      .map((file) => path.resolve(ROOT_DIR, file))
      .filter((fullPath) => fs.existsSync(fullPath));
  } catch {
    return [];
  }
}

const modifiedFiles = getModifiedFiles();
const files = modifiedFiles.length > 0 ? modifiedFiles : getAllSourceFiles(SRC_DIR);
const violations = [];

for (const filePath of files) {
  const relFile = path.relative(ROOT_DIR, filePath).replace(/\\/g, '/');
  const callerFsd = getFsdLayer(relFile);

  if (!callerFsd) continue;

  const imports = parseImports(filePath);

  for (const { specifier, line } of imports) {
    const resolvedPath = resolveModulePath(filePath, specifier);
    if (!resolvedPath) continue;

    const targetFsd = getFsdLayer(resolvedPath);
    if (!targetFsd) continue;

    // REGEL 1: Ingen feature får importera från en annan feature
    if (callerFsd.layer === 'features' && targetFsd.layer === 'features') {
      if (callerFsd.slice && targetFsd.slice && callerFsd.slice !== targetFsd.slice) {
        violations.push({
          file: relFile,
          line,
          specifier,
          rule: 'FSD-Korsvis Domänspärr',
          message:
            `Korsvis import förbjuden: Feature '${callerFsd.slice}' importerar direkt från Feature '${targetFsd.slice}'.\n` +
            `    Samverkan måste ske via de 4 godkända vägarna:\n` +
            `    1. EventBus (asynkrona händelser)\n` +
            `    2. Shared-lagret (src/shared/)\n` +
            `    3. Överliggande komposition (src/widgets/ eller src/pages/)\n` +
            `    4. Biljettklyvning (decomposing-tickets)\n`,
        });
      }
    }

    // REGEL 2: Shared-lagret får aldrig importera uppåt
    if (callerFsd.layer === 'shared') {
      if (['features', 'widgets', 'pages', 'app'].includes(targetFsd.layer)) {
        violations.push({
          file: relFile,
          line,
          specifier,
          rule: 'Lagerinversion',
          message:
            `Lagerinversion förbjuden: Shared-lagret ('src/shared') importerar från det högre lagret '${targetFsd.layer}'.\n` +
            `    Shared-lagret måste vara helt fritt från beroenden till specifika domäner eller vyer.\n`,
        });
      }
    }

    // REGEL 3: Features får inte importera från Pages eller App
    if (callerFsd.layer === 'features') {
      if (['pages', 'app'].includes(targetFsd.layer)) {
        violations.push({
          file: relFile,
          line,
          specifier,
          rule: 'Bakåtkomposition',
          message:
            `Bakåtkomposition förbjuden: Feature '${callerFsd.slice}' importerar från topplagret '${targetFsd.layer}'.\n` +
            `    Features måste vara autonoma och oberoende av presentations- och applager.\n`,
        });
      }
    }
  }
}

// ============================================================================
// RAPPORT & DETERMINISTISK EXIT-KOD
// ============================================================================

console.log('🏛️  [FSD Arkitekturkontroll v10.4] Skannar importträd under src/...');

if (violations.length > 0) {
  console.error('\n❌ ARKITEKTURVERIFIERING UNDERKÄND: Hittade överträdelser mot FSD-kontrakten:\n');
  violations.forEach((v, idx) => {
    console.error(`[Överträdelse ${idx + 1}] ${v.rule}`);
    console.error(`  Plats:    ${v.file}:${v.line}`);
    console.error(`  Import:   "${v.specifier}"`);
    console.error(`  Orsak:    ${v.message}`);
  });
  console.error(`Totalt ${violations.length} arkitekturfel. Åtgärda ovanstående innan bygget kan godkännas.`);
  process.exit(1);
}

console.log(`✅ Arkitektur godkänd! Samtliga ${files.length} filer följer FSD v10.4 och isoleringsgränserna.`);
process.exit(0);